"""A simplified outline of the UK for the family pages' maps, and the
projection that puts a longitude/latitude on it.

Source: Natural Earth 1:50m admin-0 countries (public domain), simplified
to about 446 points. Ireland is drawn faintly for context. The
projection is equirectangular scaled at 54.5 N, which is true enough for
dots on a country this size and needs no library. Generated once by a
script; the numbers are data, not code to edit by hand.
"""

import math

LON0, LON1, LAT0, LAT1 = -10.8, 2.2, 49.7, 61.0
K = 44.0
_COS = math.cos(math.radians(54.5))
W, H = 332.2, 497.2


def project(lon: float, lat: float) -> tuple[float, float] | None:
    """SVG coordinates for a point, or None when it is off the map."""
    if lon is None or lat is None or not (LON0 <= lon <= LON1 and LAT0 <= lat <= LAT1):
        return None
    return round((lon - LON0) * _COS * K, 1), round((LAT1 - lat) * K, 1)


